update pages set contenu = '{"sections":[{"type":"heros","h1":"Soudure industrielle","mecanisme":"Un soudeur évalué arrive sur votre site avec son outillage, reprend la casse et traite ce qui l''a provoquée. Travaux chiffrés à l''avance, sans embauche et sans investissement en matériel.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 prend le relais la nuit et le week-end."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"4","libelle":"agences, plus des hubs techniques, pour partir du bassin le plus proche"},{"valeur":"+ 100","libelle":"collaborateurs, partout en France"},{"valeur":"24/24 et 7/7","libelle":"astreinte, pour les sites couverts"}]},{"type":"probleme","punchline":"La production s''arrête pour quelques centimètres de cordon. Et le soudeur industriel est devenu introuvable.","puces":[{"accroche":"Le poste n''existe plus en interne.","texte":"Plus de soudeur au planning, plus de temps, plus de compétence disponible le jour où le châssis lâche."},{"accroche":"La même fixation casse tous les six mois.","texte":"Le problème n''est pas le métal, c''est la conception. Personne ne s''en occupe, tout le monde ressoude."},{"accroche":"La pièce neuve n''arrive pas.","texte":"Un arbre usé, une glissière marquée, une dent de pignon : le remplacement est indisponible et la ligne attend."},{"accroche":"Souder sur une pièce sale, c''est programmer la reprise.","texte":"Sans préparation, le cordon revient dans trois mois, au même endroit."}]},{"type":"offre","lignes":[{"prestation":"**Les fissures traitées avant la rupture** : préparation, chanfrein, reprise du cordon, examen visuel.","benefice":"Une fissure repérée tôt coûte une heure de travail. Trop tard, elle coûte la machine."},{"prestation":"**Les supports et bâtis renforcés** quand la casse revient au même endroit, avec étude de la contrainte réelle et mesure des déformations.","benefice":"La casse sort du cycle. Vous arrêtez de payer la même réparation deux fois par an."},{"prestation":"**Le rechargement de pièce usée** : apport de matière sur un arbre, une glissière, une dent de pignon, puis reprise dimensionnelle.","benefice":"L''organe repart sans attendre une pièce neuve indisponible."},{"prestation":"**La mécano-soudure de reprise** : modification d''un ensemble existant, ajout d''une platine, déplacement d''un point d''ancrage.","benefice":"Votre machine s''adapte à un nouveau produit sans être remplacée."},{"prestation":"**La tôlerie de maintenance** : carter, capot, goulotte, trémie, réparés sur place.","benefice":"Les protections qui couvrent vos opérateurs redeviennent conformes."},{"prestation":"**Le bon procédé pour le cas** : MIG, MAG, TIG, arc à électrode enrobée, brasage, choisi sur le matériau, l''épaisseur et l''accès.","benefice":"Le choix est expliqué dans le devis, pas imposé par l''habitude du poste."},{"prestation":"**Les matériaux courants de l''industrie** : acier de construction, inox, aluminium, fonte et aciers spéciaux avec préchauffage et refroidissement contrôlé.","benefice":"Une ligne agroalimentaire en inox et un bâti en acier chargé ne reçoivent pas le même traitement."},{"prestation":"**Un examen visuel systématique et un compte rendu** : préparation réalisée, procédé, métal d''apport, points à suivre.","benefice":"Le dossier s''intègre dans votre système documentaire, y compris sous certification ISO 9001."}],"prose":[{"texte":"Besoin d''un soudeur sur plusieurs semaines ? Il intervient aussi en [sous-traitance maintenance](/offres/residence/), intégré à votre équipe. Une casse métallique en cours se traite par le [dépannage industriel](/offres/depannage-industriel/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la casse et vous envoyez une photo.","texte":"Matériau, épaisseur estimée, accès à la zone, contexte. Quatre champs, ou un appel au 04 78 33 72 05."},{"titre":"Un technicien vous rappelle dans l''heure","texte":"la recherche de l''origine du défaut passe avant le chiffrage, pas l''inverse."},{"titre":"Le devis fixe le cadre","texte":"procédé retenu, métal d''apport, moyens d''accès, dimension de la zone, niveau de finition attendu."},{"titre":"La préparation décide de la tenue","texte":"meulage, dégraissage, chanfrein, protection des équipements voisins, permis de feu et mesures incendie."},{"titre":"Le soudeur intervient, machine consignée.","texte":"Apport thermique maîtrisé, gaz de protection adapté, mesures relevées au fur et à mesure pour suivre la déformation."},{"titre":"Contrôle et suivi","texte":"examen visuel, compte rendu écrit, conseil de surveillance, puis un point à distance pour vérifier que la reprise tient dans le temps."}]},{"type":"garanties","puces":[{"accroche":"Le rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30.","texte":"L''astreinte 24/24 et 7/7 couvre la nuit et le week-end sur les sites concernés."},{"accroche":"Un résultat conforme au devis, avec notre responsabilité engagée sur le travail réalisé.","texte":"Examen visuel systématique. Si un contrôle non destructif est exigé, ressuage ou radiographie, nous le faisons réaliser par un organisme spécialisé."},{"accroche":"Un poste de soudage installé en sécurité","texte":"permis de feu, écran de protection, traitement des fumées, alimentation vérifiée, balisage. La sécurité prime sur la cadence, sur votre site comme ailleurs."}]},{"type":"cta","question":"Besoin d''un soudeur sur site avant que la fissure ne devienne une rupture ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Montage d''un centre logistique, Clermont-Ferrand","texte":"12 monteurs mécaniciens et 8 engins de levage, 6 semaines de chantier, mécaniciens et chaudronniers mobilisés ensemble, livraison tenue","lienLibelle":"Étude de cas AKTID : montage d''un centre logistique","lienHref":"/preuves/aktid-centre-logistique/"},{"titre":"Montages et déplacements de machines, étanchéité et isolation","texte":"soudure et chaudronnerie parmi les domaines réunis selon le chantier, missions ciblées sur 2025","lienLibelle":"Étude de cas SOPREMA : travaux ponctuels","lienHref":"/preuves/soprema/"},{"titre":"Construction d''un site industriel de recherche et développement, matériaux bas carbone","texte":"pilotage de chantier et coordination, soudure et chaudronnerie mobilisées selon les besoins","lienLibelle":"Étude de cas ORTHUS x ECOCEM : nouveau site","lienHref":"/preuves/orthus-ecocem/"},{"titre":"Maintenance sous contrat d''un parc déployé partout en France, réalité virtuelle","texte":"périmètre technique complet, soudure et chaudronnerie comprises, depuis février 2024","lienLibelle":"Étude de cas TIMESCOPE : casques de réalité virtuelle","lienHref":"/preuves/timescope/"},{"titre":"Maintenance préventive et curative d''une fonderie et de son usinage, automobile","texte":"site tenu 7 jours sur 7 depuis octobre 2023","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"}]},{"type":"objections","questions":[{"question":"Combien coûte une intervention de soudure ?","reponse":"Le chiffrage dépend du matériau, de l''épaisseur, de l''accès et du niveau de finition attendu. Tout est établi sur devis, à partir d''une photo et d''un échange technique. Le déplacement est annoncé avant l''intervention."},{"question":"Faites-vous de la fabrication de pièces neuves ?","reponse":"Non. Notre activité est la maintenance : remise en état, renforcement, modification d''ensembles existants. Pas de découpe laser, pas de découpe plasma, pas de soudage robotisé de série. Pour une fabrication ou de la tôlerie en série, nous vous orientons vers l''atelier qui a les moyens du métier."},{"question":"Un permis de feu est-il nécessaire ?","reponse":"Presque toujours, dès qu''il y a point chaud. Nous suivons votre procédure interne, prenons les mesures de protection incendie et respectons votre plan de prévention avant de sortir l''outillage."},{"question":"Qui tient le poste chez nous ?","reponse":"Un soudeur salarié de Migen, évalué en entretien technique et comportemental, 10 % des candidats retenus. En soudure, la qualité ne se voit pas toujours sur le cordon fini : elle se joue sur le recrutement et sur la préparation."},{"question":"Intervenez-vous sur site ou faut-il déposer la pièce ?","reponse":"Les deux. La majorité des travaux se font sur place, machine consignée. Si la pièce doit partir en atelier, nous organisons la dépose et le retour, et nous restons votre interlocuteur unique."},{"question":"Couvrez-vous notre région, et les petits ateliers ?","reponse":"Oui aux deux. 4 agences, Lyon (siège), Montréal, Dubaï et Madrid, et des hubs de techniciens dans les grandes villes de France partout en France. Un bâti à reprendre vaut le déplacement autant qu''une charpente de ligne."}]},{"type":"ctaFinal","question":"Besoin que la même structure arrête de casser au même endroit ?","bouton":"Demander une intervention"}]}'::jsonb where path = '/expertises/soudure/';
